import{_ as o,o as n,c as a,a2 as i}from"./chunks/framework.1C62pOns.js";const m=JSON.parse('{"title":"Conocimiento — expresiones del pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"es/funcoes/conhecimento_pipeline.md","filePath":"es/funcoes/conhecimento_pipeline.md","lastUpdated":1787839708000}'),t={name:"es/funcoes/conhecimento_pipeline.md"};function s(l,e,r,c,d,p){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="conocimiento-—-expresiones-del-pipeline" tabindex="-1">Conocimiento — expresiones del pipeline <a class="header-anchor" href="#conocimiento-—-expresiones-del-pipeline" aria-label="Permalink to &quot;Conocimiento — expresiones del pipeline&quot;">​</a></h1><p>Los tres campos Python de la pestaña <strong>Procesamiento</strong> de un Conocimiento, usados en la ingesta desde una consulta SQL.</p><p><strong>Ninguna función de la plataforma está disponible aquí</strong> — las expresiones se ejecutan en un ámbito vacío. Lo que usted define en la <em>Declaración del pipeline</em> (funciones, constantes) queda visible para las otras dos, que se evalúan una vez por fila.</p><ul><li><strong>Declaración del pipeline</strong> — se ejecuta una vez, antes de la ingesta. Úsela para <code>import</code>, funciones auxiliares y acumuladores.</li><li><strong>Contenido del documento</strong> — una expresión que devuelve el texto a vectorizar.</li><li><strong>Metadatos del documento</strong> — una expresión que devuelve un diccionario.</li></ul><p>Hay <strong>1</strong> símbolos disponibles en este contexto.</p><h2 id="otros" tabindex="-1">Otros <a class="header-anchor" href="#otros" aria-label="Permalink to &quot;Otros&quot;">​</a></h2><h3 id="row" tabindex="-1"><code>row</code> <a class="header-anchor" href="#row" aria-label="Permalink to &quot;`row`&quot;">​</a></h3><p><em>No es una función: ya viene listo en el ámbito.</em></p><p>La fila actual de la consulta, como diccionario: <code>row.get(&#39;nombre&#39;)</code>. Solo existe en las expresiones de contenido y de metadatos — en la Declaración del pipeline aún no fue leída.</p>',9)])])}const _=o(t,[["render",s]]);export{m as __pageData,_ as default};
